class Solution:
    def maxProduct(self, nums):
        FULL = (1 << 20) - 1
        g = [0] * (FULL + 1)
        for x in nums:
            if x > g[x]: g[x] = x
        for b in range(20):
            bit = 1 << b
            for m in range(FULL + 1):
                if m & bit and g[m ^ bit] > g[m]:
                    g[m] = g[m ^ bit]
        ans = 0
        for x in nums:
            c = g[FULL ^ x]
            if c and x * c > ans: ans = x * c
        return ans

