class Solution {
public:
    long long maxProduct(vector<int>& nums) {
        const int FULL = (1 << 20) - 1;
        vector<int> g(FULL + 1, 0);
        for (int x : nums) g[x] = max(g[x], x);
        for (int b = 0; b < 20; b++)
            for (int m = FULL; m >= 0; m--)
                if (m & (1 << b)) g[m] = max(g[m], g[m ^ (1 << b)]);
        long long ans = 0;
        for (int x : nums) {
            int c = g[FULL ^ x];
            if (c) ans = max(ans, (long long)x * c);
        }
        return ans;
    }
};

