class Solution {
    public long maxProduct(int[] nums) {
        final int FULL = (1 << 20) - 1;
        int[] g = new int[FULL + 1];
        for (int x : nums) g[x] = Math.max(g[x], x);
        for (int b = 0; b < 20; b++)
            for (int m = FULL; m >= 0; m--)
                if ((m & (1 << b)) != 0) g[m] = Math.max(g[m], g[m ^ (1 << b)]);
        long ans = 0;
        for (int x : nums) {
            int c = g[FULL ^ x];
            if (c != 0) ans = Math.max(ans, (long) x * c);
        }
        return ans;
    }
}

