var maxProduct = function(nums) {
    const FULL = (1 << 20) - 1;
    const g = new Int32Array(FULL + 1);
    for (const x of nums) if (x > g[x]) g[x] = x;
    for (let b = 0; b < 20; b++) {
        const bit = 1 << b;
        for (let m = FULL; m >= 0; m--) if (m & bit && g[m ^ bit] > g[m]) g[m] = g[m ^ bit];
    }
    let ans = 0;
    for (const x of nums) {
        const c = g[FULL ^ x];
        if (c > 0 && x * c > ans) ans = x * c;
    }
    return ans;
};
